<template>
  <view class="dz-page dz-page--tabbed profile-page"><view class="dz-safe-top"/><main class="dz-container"><header class="profile-head"><view class="avatar"><image v-if="data?.avatar_url" :src="data.avatar_url" mode="aspectFill"/><text v-else>{{(data?.nickname||'达').slice(0,1)}}</text></view><view><strong class="strong-text">{{data?.nickname||'达人'}}</strong><text>已认证 · {{data?.service_city_name||'服务城市未设置'}}</text></view></header><section class="status-strip"><view><i :class="{online:data?.is_online}"/><text>{{data?.is_online?'在线接单中':'当前离线'}}</text></view><strong class="strong-text">信用良好</strong></section><h2>常用管理</h2><section class="entries"><button v-for="entry in entries" :key="entry.path" @tap="open(entry.path)"><view class="entry-icon"><image :src="entry.icon" mode="aspectFit"/></view><view><strong class="strong-text">{{entry.label}}</strong><text>{{entry.copy}}</text></view><b>›</b></button></section><button class="logout" @tap="signOut">退出登录</button></main><ProviderTabBar active="profile"/></view>
</template>
<script setup lang="ts">
import {ref} from 'vue';import{onShow}from'@dcloudio/uni-app';import ProviderTabBar from '@/components/ProviderTabBar.vue';import{logout}from '@/services/auth';import{stopLocationReporting}from '@/services/locationReporter';import{getProviderWorkbench,stopProviderOnline}from '@/services/providers';import type{ProviderWorkbench}from '@/types/api';
const data=ref<ProviderWorkbench|null>(null);const entries=[{label:'服务管理',copy:'服务项目、价格和上架状态',path:'/pages/services/index',icon:'/static/icons/service.svg'},{label:'档期管理',copy:'设置可服务时段和休息日',path:'/pages/schedule/index',icon:'/static/icons/schedule.svg'},{label:'达人订单',copy:'接单、出发和服务履约',path:'/pages/orders/index',icon:'/static/icons/orders.svg'},{label:'收入明细',copy:'本月经营与结算记录',path:'/pages/income/index',icon:'/static/icons/income.svg'}];
function open(path:string){uni.navigateTo({url:path})}async function signOut(){uni.showModal({title:'退出登录',content:data.value?.is_online?'退出后将同时停止在线接单，确定继续吗？':'确定退出达人工作端吗？',success:async result=>{if(!result.confirm)return;try{if(data.value?.is_online)await stopProviderOnline()}catch{}stopLocationReporting();await logout();uni.reLaunch({url:'/pages/auth/login'})}})}onShow(async()=>{try{data.value=(await getProviderWorkbench()).data}catch{}})
</script>
