.entries b{color:$dz-text-tertiary;font-size:36rpx;font-weight:400}.logout{height:78rpx;margin:32rpx 0;border:1rpx solid #ffcfd1;border-radius:39rpx;color:$dz-danger;background:#fff;font-size:23rpx;line-height:78rpx}</style>
